hints:
```
initialize land cells to 0 and water cells to INF
for each cell from top-left to bottom-right:
    if cell is water:
        update cell with min(top neighbor + 1, left neighbor + 1)
for each cell from bottom-right to top-left:
    if cell is water:
        update cell with min(bottom neighbor + 1, right neighbor + 1)
return max distance among all water cells
```

code.cpp:
class Solution {
public:
    int maxDistance(vector<vector<int>>& grid) {
        int n = grid.size();
        int INF = 201; // since n <= 100, max distance is 2*100 - 2 = 198

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                } else {
                    grid[i][j] = INF;
                }
            }
        }

        // Forward pass: top-left to bottom-right
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] != 0) {
                    if (i > 0) {
                        grid[i][j] = min(grid[i][j], grid[i - 1][j] + 1);
                    }
                    if (j > 0) {
                        grid[i][j] = min(grid[i][j], grid[i][j - 1] + 1);
                    }
                }
            }
        }

        // Backward pass: bottom-right to top-left
        int maxDist = 0;
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                if (grid[i][j] != 0) {
                    if (i < n - 1) {
                        grid[i][j] = min(grid[i][j], grid[i + 1][j] + 1);
                    }
                    if (j < n - 1) {
                        grid[i][j] = min(grid[i][j], grid[i][j + 1] + 1);
                    }
                    maxDist = max(maxDist, grid[i][j]);
                }
            }
        }

        if (maxDist == 0 || maxDist == INF) {
            return -1;
        }
        return maxDist;
    }
};
